```go
func printAll(n int, out chan<- int) {
    var wg sync.WaitGroup
    for i := 0; i < n; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            out <- i
        }()
    }
    wg.Wait()
    close(out)
}
