class SingleThreadSyncContext : SynchronizationContext
{
    public override void Post(SendOrPostCallback d, object state)
    {
        // 单线程上下文：回调只能由当前（被 .Result 阻塞的）线程泵取，因此不执行
    }
}

static string StartServer(int statusCode, string body, int delayMs)
{
    var listener = new TcpListener(IPAddress.Loopback, 0);
    listener.Start();
    int port = ((IPEndPoint)listener.LocalEndpoint).Port;
    var th = new Thread(() =>
    {
        try
        {
            while (true)
            {
                TcpClient client = listener.AcceptTcpClient();
                var h = new Thread(() => Handle(client, statusCode, body, delayMs));
                h.IsBackground = true;
                h.Start();
            }
        }
        catch { }
    });
    th.IsBackground = true;
    th.Start();
    return "http://127.0.0.1:" + port + "/";
}

static void Handle(TcpClient client, int statusCode, string body, int delayMs)
{
    try
    {
        using (client)
        {
            NetworkStream s = client.GetStream();
            byte[] buf = new byte[8192];
            int read = 0;
            while (read < buf.Length)
            {
                int n = s.Read(buf, read, buf.Length - read);
                if (n <= 0) break;
                read += n;
                if (Encoding.ASCII.GetString(buf, 0, read).Contains("\r\n\r\n")) break;
            }
            Thread.Sleep(delayMs);
            byte[] bodyBytes = Encoding.UTF8.GetBytes(body);
            string reason = statusCode == 200 ? "OK" : "Not Found";
            string head = "HTTP/1.1 " + statusCode + " " + reason + "\r\n" +
                          "Content-Length: " + bodyBytes.Length + "\r\n" +
                          "Connection: close\r\n\r\n";
            byte[] hb = Encoding.ASCII.GetBytes(head);
            s.Write(hb, 0, hb.Length);
            s.Write(bodyBytes, 0, bodyBytes.Length);
            s.Flush();
        }
    }
    catch { }
}

