以下 fanIn 函数合并多个通道，但运行即全员死锁（fatal error: all goroutines are asleep）。
请修复，使合并通道在所有输入耗尽后被正确关闭。不得改变函数签名，
不得引入轮询或 time.Sleep。

```go
func FanIn(chans []<-chan int) <-chan int {
	out := make(chan int)
	var wg sync.WaitGroup
	for _, ch := range chans {
		wg.Add(1)
		go func(c <-chan int) {
			defer wg.Done()
			for v := range c {
				out <- v
			}
		}(ch)
	}
	wg.Wait()   // BUG —— 主 goroutine 卡在 Wait：out 尚无接收者，
	close(out)  //           子 goroutine 的发送永久阻塞 → 互相等待
	return out
}
```

