import threading, time

counter_lock = threading.Lock()
calls = [0]

class Counter:
    @LazyProperty
    def value(self):
        with counter_lock:
            calls[0] += 1
        time.sleep(0.05)
        return {"data": [1, 2, 3]}

obj = Counter()
N = 20
barrier = threading.Barrier(N)

def worker():
    barrier.wait()
    obj.value

threads = [threading.Thread(target=worker) for _ in range(N)]
for t in threads:
    t.start()
for t in threads:
    t.join()

assert calls[0] == 1, f"value computed {calls[0]} times, expected exactly 1"
assert obj.value == {"data": [1, 2, 3]}

