requirements.referenceSolution:
function normalizeTags(array $tags): array {
    $out = $tags;
    foreach ($out as &$t) {
        $t = strtoupper(trim($t));
    }
    unset($t); // 断开引用，防止后续 foreach 写穿最后一个元素
    foreach ($out as $i => $t) {
        if ($t === '') {
            unset($out[$i]);
        }
    }
    return $out;
}

