const gen = pageItems(fetchPage);
const first = await gen.next();
if (first.done || first.value !== 1) throw new Error('first item must be 1');
let threw = false;
try {
  await gen.next();
} catch (e) {
  threw = true;
  if (e.message !== 'boom') throw new Error('wrong error message: ' + e.message);
}
if (!threw) throw new Error('error from page 2 should propagate to consumer');

