#include "ring_buffer.h"
#include "parser.h"
#include "session.h"
#include <cstring>
#include <iostream>

int main(int argc, char** argv) {
    if (argc > 1 && std::strcmp(argv[1], "--self-test") == 0) {
        RingBuffer rb(8);
        rb.write("hello", 5);
        char out[16]; size_t n = rb.read(out, sizeof(out));
        std::cout << "self-test: " << std::string(out, n) << "\n";
        return 0;
    }
    // BUG —— argc 校验后仍按 argv[1]/argv[2] 使用，越参时读野指针
    size_t cap = std::strtoul(argv[2], nullptr, 10);   // 参数顺序错位
    SessionRegistry reg;
    auto* s = reg.create(argv[1]);
    parser::feed(*s, argv[1], std::strlen(argv[1]));
    reg.destroy(s);
    reg.destroy(s);                                    // BUG —— double free
    return 0;
}

#pragma once
#include <cstddef>
class RingBuffer {
public:
    explicit RingBuffer(size_t cap);
    ~RingBuffer();
    void write(const char* data, size_t len);   // 满时应拒绝而非覆写
    size_t read(char* out, size_t maxlen);
private:
    char* buf_; size_t cap_, head_ = 0, tail_ = 0, size_ = 0;
};

#include "ring_buffer.h"
#include <cstring>

RingBuffer::RingBuffer(size_t cap) : buf_(new char[cap]), cap_(cap) {}
RingBuffer::~RingBuffer() { /* BUG —— 漏 delete[]，确定性泄漏 */ }

void RingBuffer::write(const char* d, size_t len) {
    // BUG —— 不检查剩余空间：len > 余量时覆写未读数据（off-by-wrap）
    for (size_t i = 0; i < len; i++) {
        buf_[head_] = d[i];
        head_ = (head_ + 1) % cap_;
    }
    size_ += len;                                // BUG —— size_ 可超 cap_
}

size_t RingBuffer::read(char* out, size_t maxlen) {
    size_t n = size_ < maxlen ? size_ : maxlen;
    for (size_t i = 0; i < n; i++) {
        out[i] = buf_[tail_];
        tail_ = (tail_ + 1) % cap_;
    }
    size_ -= n;
    return n;
}

#include "parser.h"
#include "session.h"
#include <cstring>

namespace parser {
// 将原始字节切分为以 \n 分隔的帧追加到会话
void feed(Session& s, const char* data, size_t len) {
    // BUG —— len 为 SIZE_MAX（上游溢出传入）时 new[SIZE_MAX] 抛 bad_alloc /
    //        截断后小分配 → 后续 memcpy 堆溢出
    char* tmp = new char[len];
    std::memcpy(tmp, data, len);
    size_t start = 0;
    for (size_t i = 0; i < len; i++) {
        if (tmp[i] == '\n') {
            s.append_frame(tmp + start, i - start);
            start = i + 1;
        }
    }
    if (start < len) s.append_frame(tmp + start, len - start);
    delete[] tmp;
}
} // namespace parser

#include "session.h"
#include <vector>

Session* SessionRegistry::create(const char* name) {
    auto* s = new Session{name};
    sessions_.push_back(s);
    return s;
}
void SessionRegistry::destroy(Session* s) {
    // BUG —— 不从 sessions_ 摘除也不判重：double destroy 即 double free
    delete s;
}

#pragma once
#include <cstddef>
#include <vector>
struct Session {
    const char* name;
    std::vector<std::vector<char>> frames;
    void append_frame(const char* d, size_t n) {
        frames.emplace_back(d, d + n);
    }
};
struct SessionRegistry {
    std::vector<Session*> sessions_;
    Session* create(const char* name);
    void destroy(Session* s);
};

