#include "ring_buffer.h"
#include "parser.h"
#include "session.h"
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <sstream>
#include <string>

static int fail(const char* m) { fprintf(stderr, "FAIL:%s\n", m); return 1; }

int main(int argc, char** argv) {
    if (argc < 2) {
        // selfcheck：往返 + 巨长输入拒绝（活会话上）+ 幂等销毁（最后）
        RingBuffer rb(16);
        rb.write("hello world", 11);
        char out[32] = {0};
        size_t n = rb.read(out, sizeof(out));
        if (std::string(out, n) != "hello world") return fail("ring roundtrip");
        SessionRegistry reg;
        Session* s = reg.create("svc");
        parser::feed(*s, "a\nbb\nccc\n", 8);
        if (s->frames.size() != 3) return fail("frame split");
        char big[8] = {0};
        try {
            parser::feed(*s, big, (size_t)-1);        // SIZE_MAX 必须被拒绝
            parser::feed(*s, big, ((size_t)1) << 42); // 超阈值必须被拒绝
        } catch (...) { return fail("huge length not rejected"); }
        reg.destroy(s); reg.destroy(s); reg.destroy(s); // 必须幂等（不崩溃）
        printf("GOLDEN-OK\n");
        return 0;
    }
    std::string mode = argv[1];
    if (mode == "file") {
        std::ifstream f(argv[2]);
        std::stringstream ss; ss << f.rdbuf();
        std::string d = ss.str();
        SessionRegistry reg;
        Session* s = reg.create("f");
        parser::feed(*s, d.data(), d.size());
        printf("frames=%zu\n", s->frames.size());
        reg.destroy(s); reg.destroy(s); // 幂等
        return 0;
    }
    if (mode == "mem") {
        for (int i = 0; i < 200; i++) {
            RingBuffer* r = new RingBuffer(64);
            r->write("x", 1);
            char b[8]; r->read(b, 8);
            delete r;
        }
        SessionRegistry reg;
        for (int i = 0; i < 200; i++) {
            Session* s = reg.create("m");
            reg.destroy(s); reg.destroy(s);
        }
        printf("MEM-OK\n");
        return 0;
    }
    if (mode == "fuzz") {
        unsigned seed = argc > 2 ? (unsigned)atoi(argv[2]) : 12345;
        SessionRegistry reg;
        Session* s = reg.create("z");
        for (int i = 0; i < 20000; i++) {
            seed = seed * 1103515245u + 12345u;
            size_t len = (seed >> 7) % 4096;
            if ((seed & 3) == 0) len = (size_t)-1 - (seed >> 9);
            char b[4096];
            memset(b, (int)seed, sizeof(b));
            try {
                parser::feed(*s, b, len);
            } catch (...) {
                fprintf(stderr, "FAIL:exception len=%zu\n", len);
                return 1;
            }
            if ((i % 997) == 0) { reg.destroy(s); reg.destroy(s); s = reg.create("z"); }
        }
        reg.destroy(s); reg.destroy(s);
        printf("FUZZ-OK\n");
        return 0;
    }
    return fail("unknown mode");
}

#include "ring_buffer.h"
#include <cstdio>
// 任务3 契约：write 返回可判真假的类型（bool），满时拒绝。
// buggy（void 返回）版本此处编译失败。
int main() {
    RingBuffer b(2);
    if (!b.write("ab", 2)) return 2;  // 恰好装满 → 接受
    if (b.write("x", 1))    return 3; // 已满 → 拒绝
    char out[2];
    b.read(out, 2);                   // 腾空
    if (!b.write("z", 1))   return 4; // 可再写
    puts("STRICT-OK");
    return 0;
}

