using Microsoft.EntityFrameworkCore;
using Shop.Models;

public class AppDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    public DbSet<Order> Orders => Set<Order>();
    public DbSet<OrderLine> Lines => Set<OrderLine>();

    protected override void OnConfiguring(DbContextOptionsBuilder ob)
        => ob.UseSqlite("Data Source=shop.db");
    // 任务3 —— 只读路径默认 NoTracking；EnableRetryOnFailure 由任务4 决策
}

namespace Shop.Models;
public class Order { public int Id { get; set; } public int CustomerId { get; set; } public List<OrderLine> Lines { get; set; } = new(); }
public class OrderLine { public int Id { get; set; } public int OrderId { get; set; } public string Sku { get; set; } = ""; public int Qty { get; set; } }

using Microsoft.EntityFrameworkCore;

namespace Shop.Services;

public record ReportRow(int OrderId, int LineCount);

public class OrderService(AppDbContext db)
{
    // BUG1 —— 每单一次 Lines 查询：经典应用层 N+1
    public async Task<List<ReportRow>> ReportAsync(int customerId)
    {
        var orders = await db.Orders.Where(o => o.CustomerId == customerId).ToListAsync();
        var rows = new List<ReportRow>();
        foreach (var o in orders)
        {
            var cnt = await db.Lines.Where(l => l.OrderId == o.Id).CountAsync();
            rows.Add(new ReportRow(o.Id, cnt));
        }
        return rows;
    }

    // BUG2 —— 逐行 SaveChanges + ChangeTracker 永不清理：万行导入 O(n²) 劣化
    public async Task<int> ImportAsync(IEnumerable<(string Sku, decimal Price)> items)
    {
        int n = 0;
        foreach (var (sku, price) in items)
        {
            db.Products.Add(new Product { Sku = sku, Price = price });
            await db.SaveChangesAsync();   // 每行一次事务
            n++;
        }
        return n;
    }

    // BUG3 —— 只读列表走跟踪查询，长生命周期上下文中内存膨胀
    public async Task<List<Product>> ListProductsAsync() => await db.Products.ToListAsync();
}

