using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Diagnostics;
using Shop.Models;
using Shop.Services;
using System.Data.Common;

namespace Shop.Tests;

public sealed class Counting : DbCommandInterceptor, ISaveChangesInterceptor
{
    public int Selects;
    public int Saves;
    private static bool IsSel(string s) => s.TrimStart().StartsWith("SELECT", StringComparison.OrdinalIgnoreCase);
    public override DbDataReader ReaderExecuted(DbCommand cmd, CommandExecutedEventData e, DbDataReader r)
    { if (IsSel(cmd.CommandText)) Selects++; return r; }
    public override ValueTask<DbDataReader> ReaderExecutedAsync(DbCommand cmd, CommandExecutedEventData e, DbDataReader r, CancellationToken ct)
    { if (IsSel(cmd.CommandText)) Interlocked.Increment(ref Selects); return base.ReaderExecutedAsync(cmd, e, r, ct); }
    public int SavedChanges(SaveChangesCompletedEventData e, int result) { Saves++; return result; }
    public ValueTask<int> SavedChangesAsync(SaveChangesCompletedEventData e, int result, CancellationToken ct)
    { Saves++; return new ValueTask<int>(result); }
}

public static class H
{
    public static (AppDbContext db, Counting cnt, SqliteConnection conn) New(bool counting = true)
    {
        var conn = new SqliteConnection("Filename=:memory:");
        conn.Open();
        var b = new DbContextOptionsBuilder<AppDbContext>().UseSqlite(conn);
        var k = new Counting();
        if (counting) b.AddInterceptors(k);
        var db = new AppDbContext(b.Options);
        db.Database.EnsureCreated();
        return (db, k, conn);
    }

    public static void Seed(AppDbContext db, int customers, int perCust, int lines)
    {
        for (int c = 1; c <= customers; c++)
            for (int o = 0; o < perCust; o++)
            {
                var ord = new Order { CustomerId = c };
                for (int l = 0; l < lines; l++)
                    ord.Lines.Add(new OrderLine { Sku = "s" + l, Qty = 1 });
                db.Orders.Add(ord);
            }
        db.SaveChanges();
        db.ChangeTracker.Clear();
    }
}

using Microsoft.EntityFrameworkCore;
using Xunit;

namespace Shop.Tests;

// 任务1：报表必须单条 SQL。buggy 版逐单查询明细 -> Selects=6 判负。
public class SqlCountReportTests
{
    [Fact]
    public async Task ReportUsesAtMostTwoSelects()
    {
        var (db, cnt, _) = H.New();
        H.Seed(db, 1, 5, 2);
        var svc = new Shop.Services.OrderService(db);
        var rows = await svc.ReportAsync(1);
        Assert.Equal(5, rows.Count);
        Assert.All(rows, r => Assert.Equal(2, r.LineCount));
        Assert.True(cnt.Selects <= 2,
            $"报表触发 {cnt.Selects} 条 SELECT（>2 即 N+1 未消除）");
    }
}

