builder.Services.AddDbContext<AppDbContext>(o =>
    o.UseSqlite("Data Source=tele.db"), ServiceLifetime.Singleton, ServiceLifetime.Singleton);
builder.Services.AddHostedService<TelemetryWriter>();   // 后台服务直接注入同一 Singleton
var app = builder.Build();
app.MapGet("/events", ...);      // 只读查询端点
