using Microsoft.EntityFrameworkCore;
public class AppDbContext : DbContext
{
    public DbSet<TeleEvent> Events => Set<TeleEvent>();
    protected override void OnConfiguring(DbContextOptionsBuilder ob)
        => ob.UseSqlite("Data Source=tele.db");
}

using Microsoft.EntityFrameworkCore;

public class TelemetryWriter(AppDbContext db) : BackgroundService
{
    // BUG2 —— 显式事务在某些异常路径不回滚/不 Dispose → 连接滞留
    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        var timer = new PeriodicTimer(TimeSpan.FromSeconds(1));
        while (await timer.WaitForNextTickAsync(ct))
        {
            var tx = await db.Database.BeginTransactionAsync(ct);
            db.Events.Add(new TeleEvent { Source = "agent", Payload = new string('x', 4096) });
            if (Random.Shared.Next(0, 10) == 0)
                continue;                     // BUG —— 异常模拟路径：不 Commit 也不 Rollback
            await db.SaveChangesAsync(ct);
            await tx.CommitAsync(ct);
            // BUG3 —— ChangeTracker 持续累积 4KB Payload 实体，从不清理
        }
    }
}

