// 任务1：DbContext 改 Scoped 后并发请求各自持有短命上下文。
public class PoolExhaustionTests : IClassFixture<AppFactory>
{
    private readonly AppFactory f;
    public PoolExhaustionTests(AppFactory f) { this.f = f; }

    [Fact]
    public async Task AllConcurrentReadsSucceed()
    {
        var client = f.CreateClient();
        var warm = await client.GetAsync("/events?last=0");
        Assert.Equal(System.Net.HttpStatusCode.OK, warm.StatusCode);
        var gate = new TaskCompletionSource();
        string firstErr = "";
        var tasks = Enumerable.Range(0, 300).Select(async _ =>
        {
            await gate.Task;
            try { var r = await client.GetAsync("/events?last=0"); return (int)r.StatusCode; }
            catch (Exception ex) { if (firstErr == "") firstErr = ex.GetType().Name + ": " + ex.Message; return -1; }
        }).ToList();
        var worker = Task.Run(async () => gate.SetResult());
        var codes = await Task.WhenAll(tasks);
        await worker;
        var bad = codes.Count(c => c != 200);
        Assert.True(bad == 0, $"{bad}/300 个请求失败 样例码={codes.FirstOrDefault(c => c != 200)} 首异常={firstErr}");
    }
}

