using Xunit;

namespace Api.Tests;

// 任务3（行为级硬判别）：持续高频写入下托管内存增量 < 150MB。
public class MemoryCeilingTests : IClassFixture<AppFactory>
{
    private const int KB = 48;
    private const int WarmN = 50;
    private const int BulkN = 3500;
    private const long CeilingBytes = 150L * 1024 * 1024;
    private readonly AppFactory f;
    public MemoryCeilingTests(AppFactory f) { this.f = f; }

    [Fact]
    public async Task ManagedMemoryStaysUnderCeiling()
    {
        var client = f.CreateClient();
        for (int i = 0; i < WarmN; i++) await U.PostAsync(client, KB, $"w{i}");
        GC.Collect(); GC.WaitForPendingFinalizers(); GC.Collect();
        var before = GC.GetTotalMemory(forceFullCollection: true);
        for (int i = 0; i < BulkN; i++)
        {
            var code = await U.PostAsync(client, KB, $"b{i}");
            if (code != 200) Assert.Fail($"POST #{i} 返回 {code}（服务已因并发冲突/宿主停止而不可用）");
        }
        GC.Collect(); GC.WaitForPendingFinalizers(); GC.Collect();
        var delta = GC.GetTotalMemory(forceFullCollection: false) - before;
        Assert.True(delta < CeilingBytes, $"托管内存增量 {delta >> 20}MB >= 150MB（ChangeTracker 未按轮次 Clear，实体滞留）");
    }
}

