package hidden

import (
    "fmt"
    "io"
    "net"
    "net/http"
    "os"
    "os/exec"
    "path/filepath"
    "syscall"
    "testing"
    "time"
)

const addr = "127.0.0.1:8080"

var baseURL = "http://" + addr

func moduleRoot() string {
    dir, err := os.Getwd()
    if err != nil {
        return "."
    }
    for {
        if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
            return dir
        }
        parent := filepath.Dir(dir)
        if parent == dir {
            return "."
        }
        dir = parent
    }
}

func buildAndStart(t *testing.T) *exec.Cmd {
    t.Helper()
    bin := "/tmp/kvsrv-hidden-bin"
    cmd := exec.Command("go", "build", "-o", bin, "./cmd/server")
    cmd.Dir = moduleRoot()
    if out, err := cmd.CombinedOutput(); err != nil {
        t.Fatalf("build: %v\n%s", err, out)
    }
    proc := exec.Command(bin)
    proc.Stdout = io.Discard
    proc.Stderr = io.Discard
    if err := proc.Start(); err != nil {
        t.Fatal(err)
    }
    if !waitPort(addr, 10*time.Second) {
        proc.Process.Kill()
        t.Fatal("server not listening on " + addr)
    }
    return proc
}

func waitPort(a string, d time.Duration) bool {
    dl := time.Now().Add(d)
    for time.Now().Before(dl) {
        c, err := net.DialTimeout("tcp", a, 300*time.Millisecond)
        if err == nil {
            c.Close()
            return true
        }
        time.Sleep(60 * time.Millisecond)
    }
    return false
}

func term(cmd *exec.Cmd) { _ = cmd.Process.Signal(syscall.SIGTERM) }

func get(t *testing.T, path string) int {
    t.Helper()
    client := &http.Client{Timeout: 3 * time.Second}
    resp, err := client.Get(baseURL + path)
    if err != nil {
        return -1
    }
    defer resp.Body.Close()
    return resp.StatusCode
}

func waitExit(cmd *exec.Cmd, limit time.Duration) (int, error) {
    done := make(chan error, 1)
    go func() { done <- cmd.Wait() }()
    select {
    case <-time.After(limit):
        cmd.Process.Kill()
        <-done
        return -999, fmt.Errorf("exit timeout >%s", limit)
    case err := <-done:
        if err == nil {
            return 0, nil
        }
        if ee, ok := err.(*exec.ExitError); ok {
            return ee.ExitCode(), nil
        }
        return -998, err
    }
}

func settle() { time.Sleep(150 * time.Millisecond) }

package hidden

import (
    "net/http"
    "testing"
    "time"
)

// 修复版语义：SIGTERM 触发优雅关闭 —— 停止接收新连接、等待在途请求完成、退出码 0。
// buggy 版无信号处理：进程被默认行为立即杀死（退出码 -15），在途请求被掐断。
func TestShutdownDrain(t *testing.T) {
    cmd := buildAndStart(t)
    type res struct {
        code int
        err  error
    }
    ch := make(chan res, 1)
    go func() {
        req, _ := http.NewRequest("GET", baseURL+"/work?key=a", nil)
        resp, err := http.DefaultClient.Do(req) // /work 内部 sleep 约 200ms
        if err != nil {
            ch <- res{-1, err}
            return
        }
        defer resp.Body.Close()
        ch <- res{resp.StatusCode, nil}
    }()
    time.Sleep(50 * time.Millisecond)
    term(cmd)
    rr := <-ch
    if rr.err != nil {
        t.Fatalf("在途请求未完成排空（SIGTERM 即杀）: %v", rr.err)
    }
    if rr.code != 200 {
        t.Fatalf("在途请求状态=%d", rr.code)
    }
    code, err := waitExit(cmd, 5500*time.Millisecond)
    if err != nil {
        t.Fatal(err)
    }
    settle()
    if code != 0 {
        t.Fatalf("退出码=%d，期望优雅关闭后为 0（-15 表示信号未被接管）", code)
    }
}

// 修复版：二次信号立即强退，但整体仍须在时限内以 0 退出。
// buggy 版第一次 TERM 即被杀死，退出码 -15。
func TestDoubleSignal(t *testing.T) {
    cmd := buildAndStart(t)
    term(cmd)
    time.Sleep(100 * time.Millisecond)
    term(cmd)
    code, err := waitExit(cmd, 5500*time.Millisecond)
    if err != nil {
        t.Fatal(err)
    }
    settle()
    if code != 0 {
        t.Fatalf("退出码=%d，期望 0（-15 表示信号未被接管）", code)
    }
}

package hidden

import (
    "errors"
    "io"
    "net"
    "os/exec"
    "testing"
    "time"
)

// 任务2：ReadTimeout=5s —— 半开慢连接必须被服务端回收。
func TestSlowConnTimeout(t *testing.T) {
    cmd := buildAndStart(t)
    defer func() { cmd.Process.Kill(); settle() }()
    c, err := net.Dial("tcp", addr)
    if err != nil {
        t.Fatal(err)
    }
    defer c.Close()
    // 只写半个请求（缺最后空行），服务端将一直等待剩余数据
    if _, err := c.Write([]byte("GET /healthz HTTP/1.1\r\nHost: x\r\n")); err != nil {
        t.Fatal(err)
    }
    start := time.Now()
    c.SetReadDeadline(time.Now().Add(9 * time.Second))
    buf := make([]byte, 64)
    _, rerr := c.Read(buf)
    elapsed := time.Since(start)
    if rerr == nil {
        t.Fatal("慢连接意外返回数据")
    }
    var ne net.Error
    if errors.As(rerr, &ne) && ne.Timeout() {
        t.Fatalf("9s 内服务端未关闭慢连接（ReadTimeout 未生效）；已等待 %v", elapsed)
    }
    if !errors.Is(rerr, io.EOF) && !errors.Is(rerr, io.ErrUnexpectedEOF) {
        t.Fatalf("非预期错误 %v（期望服务端关闭产生的 EOF）", rerr)
    }
    if elapsed > 7500*time.Millisecond {
        t.Fatalf("服务端关闭过慢：%v", elapsed)
    }
}

// 任务2：recover 中间件 —— 源码须存在显式 recover() 调用。
func TestPanicRecovery(t *testing.T) {
    grepCmd := exec.Command("grep", "-rq", "recover()", "internal/")
    grepCmd.Dir = moduleRoot()
    out, gerr := grepCmd.CombinedOutput()
    _ = out
    if gerr != nil {
        t.Fatal("internal/ 中未找到 recover() 中间件调用")
    }
    cmd := buildAndStart(t)
    defer func() { cmd.Process.Kill(); settle() }()
    if c, derr := net.Dial("tcp", addr); derr == nil {
        _, _ = c.Write([]byte("GARBAGE /\r\n\r\n"))
        c.Close()
    }
    time.Sleep(200 * time.Millisecond)
    if code := get(t, "/healthz"); code != 200 {
        t.Fatalf("畸形请求后 /healthz=%d（期望 200，服务存活）", code)
    }
}

// 任务3：/healthz 存活探针、/readyz 就绪探针
func TestReadiness(t *testing.T) {
    cmd := buildAndStart(t)
    defer func() { cmd.Process.Kill(); settle() }()
    if code := get(t, "/healthz"); code != 200 {
        t.Fatalf("/healthz=%d，期望 200", code)
    }
    if code := get(t, "/readyz"); code != 200 {
        t.Fatalf("/readyz=%d，期望 200（可写探测通过）", code)
    }
}

