// SSE 推送 —— BUG：完全无视 r.Context()，客户端断开后仍无限写入
func Stream(w http.ResponseWriter, r *http.Request) {
    fl, _ := w.(http.Flusher)
    w.Header().Set("Content-Type", "text/event-stream")
    for i := 0; ; i++ {
        fmt.Fprintf(w, "data: tick %d\n\n", i)
        if fl != nil { fl.Flush() }
        time.Sleep(time.Second)          // 既不听 Done，也不感知写失败
    }
}

package worker

import (
    "context"
    "log"
)

func StartPool(ctx context.Context) {
    jobs := make(chan int)               // 无缓冲、永不关闭
    for i := 0; i < 4; i++ {
        go func(id int) {
            for j := range jobs {        // BUG —— ctx.Done 时无人 close(jobs)
                _ = j
            }
        }(i)
    }
    go func() {
        n := 0
        for {                            // BUG —— 生产者同样不监听 ctx
            jobs <- n; n++
        }
    }()
    _ = log.Println
}

