// 上传 —— BUG：提前 return 时未读取/关闭 r.Body，连接无法复用也无法空闲
func Upload(w http.ResponseWriter, r *http.Request) {
    if r.Header.Get("X-Bad") != "" {
        w.WriteHeader(400)
        return                            // Body 泄漏点
    }
    _, _ = io.Copy(io.Discard, r.Body)
    r.Body.Close()
    w.WriteHeader(200)
}

