    if out, err := bcmd.CombinedOutput(); err != nil {
        t.Fatalf("build ./cmd/server 失败: %v\n%s", err, out)
    }
    errBuf := &bytes.Buffer{}
    cmd := exec.Command(bin)
    cmd.Stdout = io.Discard
    cmd.Stderr = errBuf
    if err := cmd.Start(); err != nil {
        t.Fatal(err)
    }
    t.Cleanup(func() {
        if cmd.Process != nil {
            _ = cmd.Process.Kill()
            _, _ = cmd.Process.Wait()
        }
    })
    dl := time.Now().Add(15 * time.Second)
    for time.Now().Before(dl) {
        c, err := net.DialTimeout("tcp", feedAddr, 300*time.Millisecond)
        if err == nil {
            _ = c.Close()
            return cmd, errBuf
        }
        time.Sleep(60 * time.Millisecond)
    }
    _ = cmd.Process.Kill()
    t.Fatalf("服务未监听 %s，stderr=%s", feedAddr, errBuf.String())
    return nil, nil
}

// openSSE 建立 SSE 连接并尽力等待首帧。
func openSSE(t *testing.T) net.Conn {
    t.Helper()
    c, err := net.Dial("tcp", feedAddr)
    if err != nil {
        t.Fatal(err)
    }
    if _, err := c.Write([]byte("GET /stream HTTP/1.1\r\nHost: x\r\n\r\n")); err != nil {
        t.Fatal(err)
    }
    buf := make([]byte, 512)
    _ = c.SetReadDeadline(time.Now().Add(3 * time.Second))
    n, _ := c.Read(buf)
    if n == 0 {
        t.Log("警告：3s 内未读到任何字节（SSE 可能未按预期开始输出）")
    }
    _ = c.SetReadDeadline(time.Time{})
    return c
}

func sigterm(cmd *exec.Cmd) { _ = cmd.Process.Signal(syscall.SIGTERM) }

// waitExitLimit 等待进程退出；超时则 kill。返回 (耗时, 退出码, 是否自然退出)。
func waitExitLimit(cmd *exec.Cmd, limit time.Duration) (time.Duration, int, bool) {
    done := make(chan struct{})
    var code int
    start := time.Now()
    go func() {
        st, _ := cmd.Process.Wait()
        if st != nil {
            code = st.ExitCode()
        }
        close(done)
    }()
    select {
    case <-done:
        return time.Since(start), code, true
    case <-time.After(limit):
        _ = cmd.Process.Kill()
        <-done
        return time.Since(start), code, false
    }
}

