type flushRec struct {
    hdr    http.Header
    writes int
    first  chan struct{}
    once   sync.Once
}

func (f *flushRec) Header() http.Header {
    if f.hdr == nil {
        f.hdr = http.Header{}
    }
    return f.hdr
}
func (f *flushRec) Write(b []byte) (int, error) {
    f.writes++
    f.once.Do(func() { close(f.first) })
    return len(b), nil
}
func (f *flushRec) WriteHeader(int) {}
func (f *flushRec) Flush()          {}

// 任务2：SSE 取消安全 —— 客户端断开（cancel）后 handler 必须在约 1s 内返回。
// buggy 版无限循环且不感知 r.Context()，永远不返回 → 超时分支判负。
func TestSSECancelSafety(t *testing.T) {
    rec := &flushRec{first: make(chan struct{})}
    ctx, cancel := context.WithCancel(context.Background())
    defer cancel()
    req := httptest.NewRequest("GET", "/stream", nil).WithContext(ctx)
    exited := make(chan struct{})
    go func() {
        api.Stream(rec, req)
        close(exited)
    }()
    select {
    case <-rec.first:
    case <-time.After(3 * time.Second):
        t.Fatal("首帧未产出（Stream 未正常工作）")
    }
    cancel()
    select {
    case <-exited:
    case <-time.After(1500 * time.Millisecond):
        t.Fatal("客户端断开后 handler 未在 1s 内退出（未监听 r.Context().Done() 且写错误未处理）")
    }
}

type trackedBody struct {
    r      *strings.Reader
    closed bool
}

func (b *trackedBody) Read(p []byte) (int, error) { return b.r.Read(p) }
func (b *trackedBody) Close() error               { b.closed = true; return nil }

// 任务2：upload 错误路径必须 drain 并关闭 r.Body。
// buggy 版提前 return 时两者皆无 → 双断言判负。
func TestUploadBodyHygiene(t *testing.T) {
    body := &trackedBody{r: strings.NewReader("hello-body")}
    h := http.HandlerFunc(api.Upload)
    w := httptest.NewRecorder()
    req := httptest.NewRequest("POST", "/upload", body)
    req.Header.Set("X-Bad", "1")
    h.ServeHTTP(w, req)
    if w.Code != 400 {
        t.Fatalf("X-Bad 请求期望 400，得到 %d", w.Code)
    }
    if !body.closed {
        t.Fatal("错误路径未关闭 r.Body（连接无法复用/句柄泄漏）")
    }
    if remain := body.r.Len(); remain != 0 {
        t.Fatalf("错误路径未 drain r.Body：仍剩 %d 字节未消费", remain)
    }
}

