// 任务1：全组件接入统一 ctx —— 源码证据 + 端到端（SIGTERM 后 SSE 连接被服务端关闭）。
func TestAllComponentsCancel(t *testing.T) {
    pool, err := os.ReadFile(filepath.Join(moduleRoot(), "internal", "worker", "pool.go"))
    if err != nil {
        t.Fatalf("读取 internal/worker/pool.go: %v", err)
    }
    if !strings.Contains(string(pool), "ctx.Done") {
        t.Fatal("worker/pool.go 未接入统一 ctx（生产者/消费者均未监听 ctx.Done），取消后 goroutine 泄漏")
    }
    met, err := os.ReadFile(filepath.Join(moduleRoot(), "internal", "metrics", "metrics.go"))
    if err != nil {
        t.Fatalf("读取 internal/metrics/metrics.go: %v", err)
    }
    if !strings.Contains(string(met), "Stop") && !strings.Contains(string(met), "ctx") && !strings.Contains(string(met), "Done") {
        t.Fatal("metrics.go 的 ticker 从不停止（无 Stop/ctx 接入），心跳 goroutine 永存")
    }
    cmd, _ := startFeedServer(t)
    c := openSSE(t)
    sigterm(cmd)
    closed := make(chan error, 1)
    go func() {
        buf := make([]byte, 64)
        _ = c.SetReadDeadline(time.Now().Add(4 * time.Second))
        _, rerr := c.Read(buf)
        closed <- rerr
    }()
    select {
    case <-closed:
        // 读到 EOF/错误即视为连接已被服务端关闭（ctx 贯穿到 handler）
    case <-time.After(4200 * time.Millisecond):
        t.Fatal("SIGTERM 后 SSE 连接 4s 内未被服务端关闭（组件/handler 未随 ctx 退出）")
    }
}

// 任务3：SIGTERM 后进程必须在 5s grace + 余量内退出。
func TestExitDeadline(t *testing.T) {
    cmd, _ := startFeedServer(t)
    c := openSSE(t)
    sigterm(cmd)
    el, _, exited := waitExitLimit(cmd, 5500*time.Millisecond)
    _ = c.Close()
    if !exited {
        t.Fatalf("SIGTERM 后 %.1fs 未退出（Shutdown 未带超时 ctx 或组件未接 ctx）", el.Seconds())
    }
}

// 任务4：卡死诊断 —— 源码须有 goroutine 栈 dump 能力。
func TestDumpOnStuck(t *testing.T) {
    joined := ""
    if b, err := os.ReadFile(filepath.Join(moduleRoot(), "cmd", "server", "main.go")); err == nil {
        joined += string(b)
    }
    if b, err := os.ReadFile(filepath.Join(moduleRoot(), "internal", "server", "server.go")); err == nil {
        joined += string(b)
    }
    if !strings.Contains(joined, "runtime.Stack") && !strings.Contains(joined, "pprof.Lookup(\"goroutine\")") {
        t.Fatal("任务4 未实现：应在关闭超时时用 runtime.Stack / pprof.Lookup(goroutine) 向 stderr dump 栈再强退")
    }
    cmd, errBuf := startFeedServer(t)
    c := openSSE(t)
    sigterm(cmd)
    el, _, exited := waitExitLimit(cmd, 6500*time.Millisecond)
    _ = c.Close()
    if !exited {
        t.Fatalf("卡死场景 %.1fs 内既未优雅退出也无超时强退兜底", el.Seconds())
    }
    if el > 5200*time.Millisecond && !strings.Contains(errBuf.String(), "goroutine") {
        t.Fatalf("退出耗时 %.1fs（走了超时路径）但 stderr 中没有 goroutine dump 诊断信息", el.Seconds())
    }
}

