  console.log("ALL_DONE");
}

main().catch((e) => { console.error("fatal", e); process.exit(1); });

const { EventEmitter } = require("events");

class Queue extends EventEmitter {
  constructor({ concurrency }) {
    super();
    this.concurrency = concurrency;
    this.items = [];
    this.running = 0;
  }
  push(job) { this.items.push(job); }
  async drainUntilEmpty() {
    // BUG —— 同步执行 job.fn()：单个重活阻塞整个事件循环；
    //        Promise 拒绝无人接住 → unhandledRejection
    while (this.items.length || this.running) {
      while (this.items.length && this.running < this.concurrency) {
        const job = this.items.shift();
        this.running++;
        job.fn(job.ctx).then((r) => {
          this.emit("done", job, r);
          this.running--;
        });
        // BUG —— 没有 .catch：rejected promise 未处理
      }
      await new Promise((r) => setImmediate(r));
    }
  }
}
module.exports = { Queue };

const http = require("http");

function fetchOnce(url, timeoutMs) {
  return new Promise((resolve, reject) => {
    const req = http.get(url, (res) => {
      res.resume();
      res.statusCode === 200 ? resolve("ok") : reject(new Error("status " + res.statusCode));
    });
    req.setTimeout(timeoutMs, () => { req.destroy(new Error("timeout")); });
    req.on("error", reject);
  });
}

// BUG —— 重试用 setInterval 反复触发，从不 clearInterval；
//        失败耗尽后错误被静默丢弃
function makeHttpJob({ id, url, retries = 3 }) {
  return {
    id, ctx: { url },
    fn: async () => {
      let attempt = 0;
      return await new Promise((resolve, reject) => {
        const timer = setInterval(async () => {
          try {
            const r = await fetchOnce(url, 800);
            resolve(r);                       // 忘记 clearInterval(timer)
          } catch (e) {
            if (++attempt > retries) {
              reject(e);                      // 且这里也没有 clearInterval
            }
          }
        }, 100);
      });
    },
  };
}
module.exports = { makeHttpJob };

// 任务截止时间 —— BUG：基于 Date.now() 的墙钟，系统时间回拨即漂移
function makeDeadline(ms) {
  const end = Date.now() + ms;
  return {
    expired: () => Date.now() >= end,
    remaining: () => Math.max(0, end - Date.now()),
  };
}
module.exports = { makeDeadline };

