      let n = 0; res.on('data', c => n += c.length);
      res.on('end', () => resolve({ status: res.statusCode, bytes: n }));
    });
    r.on('timeout', () => { r.destroy(new Error('client-timeout')); });
    r.on('error', e => resolve({ status: -1, err: String(e && e.message) }));
  });
