  return false;
}
function startServer() {
  const p = spawn(process.execPath, ['src/server.js'], { cwd: ROOT, stdio: 'ignore' });
  return p;
}
function rssKB(pid) { try { const t = fs.readFileSync(`/proc/${pid}/status`, 'utf8'); const m = /VmRSS:\s+(\d+)/.exec(t); return m ? +m[1] : -1; } catch { return -1; } }
function assert(cond, msg) { if (!cond) { console.error('FAIL:', msg); process.exit(1); } }
