package com.shop.order.hidden;

import java.util.List;

import com.shop.customer.Customer;
import com.shop.customer.CustomerRepository;
import com.shop.order.Order;
import com.shop.order.OrderRepository;
import com.shop.order.OrderService;
import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import org.hibernate.SessionFactory;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.transaction.annotation.Transactional;

import static org.junit.jupiter.api.Assertions.*;

// 任务1：消除 N+1 —— itemCounts 对 5 单的查询必须 <= 2 条 SQL。
// buggy 版逐单触发 items 懒加载：1 条订单查询 + 5 条明细查询 = 6 条 -> 判负；
// 若懒加载在会话外直接抛 LazyInitializationException 同样判负。
@SpringBootTest(properties = "spring.jpa.properties.hibernate.generate_statistics=true")
@Transactional
class NPlusOneIT {

    @PersistenceContext
    EntityManager em;
    @Autowired OrderRepository orders;
    @Autowired CustomerRepository customers;
    @Autowired OrderService service;

    @Test
    void itemCountsUsesAtMostTwoSqlStatements() {
        var c = customers.save(new Customer());
        for (int i = 0; i < 5; i++) {
            var o = new Order();
            o.setCustomerId(c.getId());
            for (int j = 0; j < 2; j++) {
                var it = new Order.Item();
                it.setSku("sku-" + j);
                it.setQty(1);
                it.setOrder(o);
                o.getItems().add(it);
            }
            orders.save(o);
        }
        em.flush();
        em.clear(); // 脱管全部实体，确保后续加载全部真实走库

        var sf = em.getEntityManagerFactory().unwrap(SessionFactory.class);
        sf.getStatistics().clear();

        var counts = service.itemCounts(c.getId());

        assertEquals(5, counts.size());
        assertEquals(List.of(2, 2, 2, 2, 2), counts);
        long stmts = sf.getStatistics().getPrepareStatementCount();
        assertTrue(stmts <= 2,
                "itemCounts 触发了 " + stmts + " 条 SQL（>2 即 N+1：需 JOIN FETCH/@EntityGraph 或投影）");
    }
}

