    private boolean adviceExists() throws IOException {
        Path root = Paths.get("src", "main", "java");
        if (!Files.isDirectory(root)) return false;
        try (Stream<Path> walk = Files.walk(root)) {
            return walk.filter(p -> p.toString().endsWith(".java")).anyMatch(p -> {
                try {
                    String s = Files.readString(p);
                    return s.contains("@RestControllerAdvice") || s.contains("@ControllerAdvice");
                } catch (IOException e) {
                    return false;
                }
            });
        }
    }
}

