package batch;
import java.util.*;

// BUG —— ArrayList + synchronized 每方法加锁，无背压、无阻塞语义
public class TaskQueue {
    private final List<Task> q = new ArrayList<>();
    public synchronized void put(Task t) { q.add(t); }
    public synchronized Task take() {
        return q.isEmpty() ? null : q.remove(0);
    }
    public synchronized int size() { return q.size(); }
}

package batch;
import java.util.concurrent.*;

public class WorkerPool {
    private final ExecutorService pool = Executors.newFixedThreadPool(4);

    public void submit(Task t, Callback cb) {
        pool.execute(() -> cb.done(t, run(t)));
    }
    private boolean run(Task t) {
        try { Thread.sleep(t.payloadMillis()); return true; }
        catch (InterruptedException e) { Thread.currentThread().interrupt();
            return false;
        }
    }
    // BUG —— 无任何关闭语义；TaskQueue 与执行池互不相通（演示入口投递的任务无人消费）
}

package batch;

@FunctionalInterface
public interface Callback { void done(Task task, boolean ok); }

package batch;

// BUG —— 普通整型计数器，多线程回调下存在丢失更新
public class Stats {
    private int submitted = 0, completed = 0, failed = 0;

    public void incSubmitted() { submitted++; }
    public void incDone(boolean ok) { if (ok) completed++; else failed++; }
    public String report() {
        return "submitted=" + submitted + " completed=" + completed + " failed=" + failed;
    }
    public int getSubmitted() { return submitted; }
    public int getCompleted() { return completed; }
    public int getFailed()    { return failed; }
}

package batch;

public class Main {
    public static void main(String[] args) throws Exception {
        TaskQueue q = new TaskQueue();
        Stats s = new Stats();
        WorkerPool p = new WorkerPool();
        p.bind(q, s);
        p.start();                                  // 当前实现不存在 —— 编译期即暴露断层
        for (int i = 0; i < 1000; i++) {
            q.put(new Task("t" + i, 10));
            s.incSubmitted();
        }
        Runtime.getRuntime().addShutdownHook(new Thread(() ->
            System.err.println("[hook] " + s.report())));   // 进程退出即在途任务丢失
        Thread.sleep(60_000);
        System.out.println(s.report());
    }
}

