package batch;

public final class BatchAssert {
    private BatchAssert() {}
    public static void ok(boolean cond, String msg) {
        if (!cond) { System.err.println("FAIL: " + msg); System.exit(1); }
    }

    /** 反射调 put：兼容声明/未声明受检异常的两种实现。 */
    public static void put(TaskQueue q, Task t) throws Exception {
        try {
            q.getClass().getMethod("put", Task.class).invoke(q, t);
        } catch (java.lang.reflect.InvocationTargetException e) {
            Throwable c = e.getCause();
            if (c instanceof Exception) throw (Exception) c;
            throw (Error) c;
        }
    }

    /** 反射调 take：同上。 */
    public static Object take(TaskQueue q) throws Exception {
        try {
            return q.getClass().getMethod("take").invoke(q);
        } catch (java.lang.reflect.InvocationTargetException e) {
            Throwable c = e.getCause();
            if (c instanceof Exception) throw (Exception) c;
            throw (Error) c;
        }
    }
}

package batch;

// 任务1：队列满时 put 必须阻塞（背压），take 后解除。
// 契约：存在 TaskQueue(int capacity) 构造（任务1 明示“构造可配”）。
// buggy 版既无该构造也无界 -> 双重判负。
public class BackpressureIT {
    public static void main(String[] args) throws Exception {
        TaskQueue q;
        try {
            q = (TaskQueue) Class.forName("batch.TaskQueue")
                    .getConstructor(int.class).newInstance(4);
        } catch (ReflectiveOperationException e) {
            System.err.println("FAIL: TaskQueue 缺少 TaskQueue(int capacity) 构造（任务1 要求容量可配）");
            System.exit(1);
            return;
        }
        final TaskQueue qq = q;
        for (int i = 0; i < 4; i++) BatchAssert.put(qq, new Task("t" + i, 1));
        final Exception[] perr = new Exception[1];
        Thread producer = new Thread(() -> {
            try { BatchAssert.put(qq, new Task("blocked", 1)); }
            catch (Exception e) { perr[0] = e; }
        });
        producer.setDaemon(true);
        producer.start();
        Thread.sleep(400);
        if (perr[0] != null) {
            System.err.println("FAIL: put 抛出异常而非阻塞: " + perr[0]);
            System.exit(1);
        }
        BatchAssert.ok(producer.isAlive(), "队列满时 put 必须阻塞（当前立即返回=无背压无限堆积）");
        BatchAssert.take(qq);
        Thread.sleep(400);
        BatchAssert.ok(!producer.isAlive(), "take 之后阻塞的 put 应完成");
        System.out.println("BACKPRESSURE-OK");
    }
}

package batch;

import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

// 任务2：优雅关闭 —— 在途任务排空、停止受理新任务、超时有界、报告无未完成。
// buggy 版 shutdown 空实现：late 探针被执行 -> 判负。
public class GracefulShutdownIT {
    public static void main(String[] args) throws Exception {
        TaskQueue q = new TaskQueue();
        Stats s = new Stats();
        WorkerPool p = new WorkerPool();
        p.bind(q, s);
        p.start();
        AtomicInteger done = new AtomicInteger();
        CountDownLatch all = new CountDownLatch(40);
        for (int i = 0; i < 40; i++) {
            p.submit(new Task("j" + i, 100), (t, okv) -> { done.incrementAndGet(); all.countDown(); });
        }
        Thread.sleep(150);
        p.shutdown();
        final AtomicBoolean lateRan = new AtomicBoolean(false);
        try {
            p.submit(new Task("late", 0), (t, okv) -> lateRan.set(true));
        } catch (RuntimeException rejected) {
            // 以异常方式拒绝同样正确
        }
        Object unfinished = p.awaitTermination(6000);
        BatchAssert.ok(all.await(6, TimeUnit.SECONDS),
                "shutdown 后在途任务未在时限内排空 done=" + done.get() + "/40");
        Thread.sleep(200);
        BatchAssert.ok(!lateRan.get(), "shutdown 后仍受理并执行了新任务（停止受理语义缺失）");
        boolean empty = unfinished == null
                || (unfinished instanceof java.util.List<?> l && l.isEmpty());
        BatchAssert.ok(empty, "awaitTermination 应返回空清单（全部任务已终态）");
        System.out.println("GRACEFUL-SHUTDOWN-OK");
        System.exit(0);
    }
}

