import java.util.concurrent.*;

// 任务3：守恒 submitted == completed + failed，snapshot 一致。
// 失败注入约定：payloadMillis < 0 表示任务执行失败。
// buggy 版失败任务回调被跳过（latch 不归零）且无人调用 incDone -> 双重判负。
public class StatsConservationTest {
    public static void main(String[] args) throws Exception {
        TaskQueue q = new TaskQueue();
        Stats s = new Stats();
        WorkerPool p = new WorkerPool();
        p.bind(q, s);
        p.start();
        int total = 16 * 250;
        CountDownLatch latch = new CountDownLatch(total);
        ExecutorService producers = Executors.newFixedThreadPool(16);
        for (int i = 0; i < total; i++) {
            final int idx = i;
            final boolean failTask = (i % 7 == 0);
            producers.submit(() -> {
                s.incSubmitted();
                p.submit(new Task("c" + idx, failTask ? -1 : 0),
                        (t, okv) -> latch.countDown());
                return null;
            });
        }
        producers.shutdown();
        BatchAssert.ok(latch.await(60, TimeUnit.SECONDS),
                "60s 内未收齐全部回调（失败路径绕过回调，或消费者缺失/死锁）");
        p.shutdown();
        p.awaitTermination(5000);
        var snap = s.snapshot();
        int doneN = snap.getOrDefault("completed", s.getCompleted());
        int failedN = snap.getOrDefault("failed", s.getFailed());
        BatchAssert.ok((long) doneN + failedN == (long) total,
                "守恒 completed+failed==submitted 失败 snapshot=" + snap + " total=" + total);
        System.out.println("STATS-CONSERVATION-OK");
    }
}

package batch;

import java.util.concurrent.*;

// 任务4：必败任务重试至多 2 次（共 <=3 次执行）后以 ok=false 回调并计入 failed。
// 失败注入约定：payloadMillis < 0 表示任务执行抛 RuntimeException。
// buggy 版异常直接逃逸、回调永不触发 -> latch 超时判负。
public class RetryCapTest {
    public static void main(String[] args) throws Exception {
        TaskQueue q = new TaskQueue();
        Stats s = new Stats();
        WorkerPool p = new WorkerPool();
        p.bind(q, s);
        p.start();
        CountDownLatch latch = new CountDownLatch(1);
        s.incSubmitted();
        final boolean[] okFlag = {true};
        p.submit(new Task("doomed", -1), (t, okv) -> { okFlag[0] = okv; latch.countDown(); });
        BatchAssert.ok(latch.await(15, TimeUnit.SECONDS),
                "必败任务未收到失败回调（异常路径绕过回调或工作线程死亡）");
        BatchAssert.ok(!okFlag[0], "必败任务的回调 ok 必须为 false");
        int failed = Math.max(s.getFailed(), s.snapshot().getOrDefault("failed", 0));
        BatchAssert.ok(failed >= 1, "failed 计数未增加");
        p.shutdown();
        p.awaitTermination(5000);
        System.out.println("RETRY-CAP-OK");
    }
}

