import threading
from tailer import Tailer
from parser import parse_line
from sink import BatchSink
from checkpoint import Checkpoint

class LogAgent:
    def __init__(self, path: str, sink: BatchSink):
        self.tailer = Tailer(path)
        self.sink = sink
        self.checkpoint = Checkpoint("agent.chkpt")
        self._stop = threading.Event()

    def run(self):
        while not self._stop.is_set():
            line, offset = self.tailer.next_line(timeout=0.5)
            if line is None:
                continue
            event = parse_line(line)
            if event is None:
                continue          # 任务2 —— 坏行静默丢失
            self.sink.add(event)
        self.checkpoint.save(self.tailer.offset)   # 任务1 —— 先于 flush

    def stop(self):
        self._stop.set()

class Tailer:
    """增量读取追加写日志文件，维护字节偏移。"""
    def __init__(self, path: str):
        self.path = path
        self.offset = 0
        self._fh = open(path, "r", encoding="utf-8")

    def next_line(self, timeout=None):
        line = self._fh.readline()
        if line == "":
            return None, self.offset
        self.offset += len(line.encode("utf-8"))
        return line.rstrip("\n"), self.offset

    def seek_to(self, offset: int):
        self.offset = offset
        self._fh.seek(offset)

import re, json

LINE_RE = re.compile(r'^(\S+) (\S+) (\S+) \[(.+?)\] "(.+?)" (\d{3}) (\d+)$')

def parse_line(line: str):
    m = LINE_RE.match(line)
    if not m:
        return None
    ip, ident, user, ts, req, status, size = m.groups()
    return json.dumps({"ip": ip, "ts": ts, "req": req,
                       "status": int(status), "size": int(size)})

import json

class BatchSink:
    def __init__(self, path="events.ndjson", batch_size=100):
        self.path = path
        self.batch_size = batch_size
        self.buffer = []

    def add(self, event: str):
        self.buffer.append(event)
        if len(self.buffer) >= self.batch_size:
            self.flush()

    def flush(self):
        if self.buffer:
            with open(self.path, "a", encoding="utf-8") as f:
                f.write("\n".join(self.buffer) + "\n")
            self.buffer.clear()

    def close(self):
        pass                        # BUG —— close 不 flush，缓冲丢失

import json

class Checkpoint:
    def __init__(self, path: str):
        self.path = path
        try:
            with open(path) as f:
                self.value = json.load(f)["offset"]
        except Exception:
            self.value = 0

    def save(self, offset: int):
        with open(self.path, "w") as f:
            json.dump({"offset": offset}, f)

