import heapq, threading

class Scheduler:
    def __init__(self):
        self._heap = []
        self._cv = threading.Condition()

    def submit(self, job_id: str, priority: int, payload: dict):
        with self._cv:
            heapq.heappush(self._heap, (priority, job_id, payload))
            self._cv.notify()

    def next_job(self, timeout=None):
        with self._cv:
            if not self._heap and not self._cv.wait(timeout):
                return None
            # BUG —— 数字越小优先级越高，持续高优负载会饿死低优任务
            return heapq.heappop(self._heap)

from retry import schedule_retry

class Worker(threading.Thread):
    def __init__(self, sched, storage, metrics, daemon=True):
        super().__init__(daemon=daemon)
        self.sched, self.storage, self.metrics = sched, storage, metrics

    def run(self):
        while True:
            job = self.sched.next_job(timeout=1)
            if job is None:
                continue
            _, job_id, payload = job
            self.storage.mark(job_id, "RUNNING")
            try:
                handle(payload)
                self.storage.mark(job_id, "DONE")
                self.metrics.inc("done")
            except Exception:
                self.metrics.inc("failed_attempt")
                schedule_retry(self.sched, job_id, payload)

def handle(payload: dict):
    raise NotImplementedError   # 由测试注入

class Metrics:
    def __init__(self):
        self.counters = {}      # BUG —— 多线程 inc 存在丢失更新

    def inc(self, name):
        self.counters[name] = self.counters.get(name, 0) + 1

    def snapshot(self):
        return dict(self.counters)

