import inspect, os, sys, time, unittest
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
sys.path.insert(0, ROOT)

class FakeSched:
    def __init__(self):
        self.calls = 0
    def submit(self, *a, **k):
        self.calls += 1

class T(unittest.TestCase):
    def test_exponential_backoff_detected(self):
        import retry
        fs = FakeSched()
        delays = []
        real_sleep = time.sleep
        time.sleep = lambda s: delays.append(float(s))
        try:
            for _ in range(7):
                self._call(retry, fs)
        finally:
            time.sleep = real_sleep
        if not delays:
            delays = self._probe_delay_fn(retry)
        self.assertIsNotNone(delays and delays or None,
            '未检测到退避延迟（schedule_retry 立即无条件重投 = 固定间隔重试）')
        self.assertGreater(delays[0], 0.2, f'首次退避应约 1s（base=1s），实测 {delays[0]}')
        for i in range(1, len(delays)):
            lo, hi = delays[i - 1] * 1.3, delays[i - 1] * 3.5
            self.assertGreaterEqual(delays[i], lo,
                f'第 {i} 次延迟 {delays[i]:.2f}s 未按 factor≈2 递增')
            self.assertLessEqual(delays[i], hi,
                f'第 {i} 次延迟 {delays[i]:.2f}s 增长异常')
        self.assertLess(delays[-1], 120, '延迟未受 cap=60s 约束')
        if len(delays) >= 3:
            ratios = [round(delays[i + 1] / delays[i], 6) for i in range(len(delays) - 1)]
            if len(set(ratios)) == 1:
                print('WARN: 未观察到随机抖动（ratios 完全一致）', file=sys.stderr)

    def _call(self, retry, fs):
        for kw in ({'error': 'boom'}, {}):
            try:
                retry.schedule_retry(fs, 'j1', {}, **kw)
                return
            except TypeError:
                continue
        retry.schedule_retry(fs, 'j1', {})

    def _probe_delay_fn(self, retry):
        for name, fn in vars(retry).items():
            if callable(fn) and not name.startswith('_') and \
               any(k in name.lower() for k in ('delay', 'backoff', 'interval')):
                try:
                    sig = inspect.signature(fn)
                    if len(sig.parameters) == 1:
                        return [float(fn(i)) for i in range(6)]
                except (TypeError, ValueError):
                    pass
        return None

