class FakeSched:
    def __init__(self):
        self.n = 0
    def submit(self, *a, **k):
        self.n += 1

class T(unittest.TestCase):
    def test_permanent_failure_enters_dead_letter_and_stops_resubmitting(self):
        """契约：连续失败最多重试 5 次，超限写入 storage 的 dead_letter 表并附错误信息。
        兼容两种实现：attempt 显式传参 / 内部按 job_id 计数。"""
        import retry
        from storage import JobStore
        db = os.path.join(tempfile.mkdtemp(), 'jobs.db')
        store = JobStore(db)
        fs = FakeSched()
        real_sleep = time.sleep
        time.sleep = lambda *_a, **_k: None
        try:
            for i in range(1, 9):   # 8 连败 > 上限 5
                self._call(retry, store, fs, attempt=i)
        finally:
            time.sleep = real_sleep
        row = self._find_dead(store, db, 'dl-job')
        self.assertIsNotNone(row, '重试超限后未进入 dead_letter（storage 表/API 均未找到该任务）')
        self.assertLessEqual(fs.n, 6,
            f'schedule_retry 触发了 {fs.n} 次重投（>6 = 无重试上限，无限重试）')

    def _call(self, retry, store, fs, attempt):
        for kw in (
            {'storage': store, 'error': 'permanent-fail', 'attempt': attempt},
            {'storage': store, 'attempt': attempt},
            {'storage': store, 'error': 'permanent-fail'},
            {'storage': store},
            {'error': 'permanent-fail'},
            {},
        ):
            try:
                retry.schedule_retry(fs, 'dl-job', {'n': attempt}, **kw)
                return
            except TypeError:
                continue
        self.fail('schedule_retry 无任何兼容签名可调用')

    def _find_dead(self, store, db_path, job_id):
        for name in ('get_dead_letter', 'list_dead_letters', 'dead_letters', 'get_dead'):
            fn = getattr(store, name, None)
            if callable(fn):
                for arg in ((), (job_id,)):
                    try:
                        out = fn(*arg)
                        if out:
                            return out
                    except Exception:
                        pass
        conn = sqlite3.connect(db_path)
        try:
            tables = [r[0] for r in conn.execute(
                "SELECT name FROM sqlite_master WHERE type='table'")]
            for t in tables:
                if 'dead' not in t.lower():
                    continue
                cols = [r[1] for r in conn.execute(f'PRAGMA table_info({t})')]
                for c in cols:
                    try:
                        rows = conn.execute(
                            f'SELECT * FROM {t} WHERE CAST({c} AS TEXT) LIKE ?',
                            (f'%{job_id}%',)).fetchall()
                        if rows:
                            return rows[0]
                    except sqlite3.Error:
                        continue
        finally:
            conn.close()
        return None

