use tokio::net::TcpStream;

pub async fn handle(mut sock: TcpStream, state: Arc<AppState>) {
    let mut buf = vec![0u8; 512];
    loop {
        tokio::select! {
            // BUG —— read 分支不具取消安全性：部分读取的字节数被丢弃
