#![allow(dead_code)]
use std::io::{Read, Write};
use std::net::TcpStream;
use std::path::PathBuf;
use std::process::{Child, Command, Stdio};
use std::thread;
use std::time::{Duration, Instant};

pub const ADDR: &str = "127.0.0.1:7878";

pub struct Server {
    pub child: Child,
}

impl Server {
    pub fn pid(&self) -> u32 {
        self.child.id()
    }
}

impl Drop for Server {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
        thread::sleep(Duration::from_millis(400));
    }
}

fn find_bin() -> Option<PathBuf> {
    for p in ["target/debug/kv-server", "target/release/kv-server"] {
        let pb = PathBuf::from(p);
        if pb.exists() {
            return Some(pb);
        }
    }
    None
}

pub fn start_server() -> Server {
    if find_bin().is_none() {
        let out = Command::new("cargo")
            .arg("build")
            .output()
            .expect("运行 cargo build 失败");
        assert!(
            out.status.success(),
            "workspace 编译失败:\n{}",
            String::from_utf8_lossy(&out.stderr)
        );
    }
    let bin = find_bin().expect("找不到 kv-server 可执行文件");
    let mut child = Command::new(bin)
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn()
        .expect("启动 kv-server 失败");
    let dl = Instant::now() + Duration::from_secs(15);
    let mut up = false;
    while Instant::now() < dl {
        if TcpStream::connect(ADDR).is_ok() {
            up = true;
            break;
        }
        thread::sleep(Duration::from_millis(60));
    }
    if !up {
        let _ = child.kill();
        let _ = child.wait();
        panic!("server 未监听 {}", ADDR);
    }
    Server { child }
}

pub fn req(cmd: &[u8]) -> String {
    let mut s = TcpStream::connect(ADDR).expect("connect");
    s.set_read_timeout(Some(Duration::from_secs(5))).unwrap();
    s.set_write_timeout(Some(Duration::from_secs(5))).unwrap();
    s.write_all(cmd).expect("write");
    let mut buf = vec![0u8; 65536];
    let n = s.read(&mut buf).unwrap_or(0);
    String::from_utf8_lossy(&buf[..n]).to_string()
}

pub fn fd_count(pid: u32) -> usize {
    std::fs::read_dir(format!("/proc/{}/fd", pid))
        .map(|d| d.filter_map(|e| e.ok()).count())
        .unwrap_or(usize::MAX)
}

mod common;
use common::*;
use std::thread;
use std::time::{Duration, Instant};

// 任务1：压测无死锁 —— 40 并发连接 × 50 请求。
// buggy 版 std Mutex 跨 await 持有（临界区内 sleep 1ms）导致全局串行化；
// 修复版（tokio Mutex 或缩短临界区）应在时限内轻松完成。
#[test]
fn stress_no_deadlock() {
    let _srv = start_server();
    let t0 = Instant::now();
    let mut hs = Vec::new();
    for w in 0..40usize {
        hs.push(thread::spawn(move || {
            for i in 0..50usize {
                let cmd = format!("w{}-k{}\n", w, i);
                let r = req(cmd.as_bytes());
                assert!(
                    !r.is_empty(),
                    "空响应（连接被服务端丢弃）w{}-k{}",
                    w,
                    i
                );
            }
        }));
    }
    for h in hs {
        h.join().expect("工作线程 panic");
    }
    let el = t0.elapsed();
    assert!(
        el < Duration::from_secs(90),
        "2000 请求耗时 {:?}（>90s 疑似跨 await 持锁串行化/死锁）",
        el
    );
}

mod common;
use common::*;
use std::io::{Read, Write};
use std::net::TcpStream;
use std::process::Command;
use std::thread;
use std::time::Duration;

// 任务2/4：取消安全 + 排空 —— 在途半请求期间收到 SIGINT：
// 修复版进入排空，在途连接完整应答（MISS）；
// buggy 版 select! 的 ctrl_c 分支直接完成 → handler 返回、连接被丢弃 → 读到 EOF 判负。
#[test]
fn cancel_safety_partial_reads_preserved() {
    let srv = start_server();
    let mut s = TcpStream::connect(ADDR).expect("connect");
    s.set_read_timeout(Some(Duration::from_secs(5))).unwrap();
    // 1) 分片写入，制造部分读取窗口
    for chunk in b"split-key-xyz".chunks(4) {
        s.write_all(chunk).unwrap();
        s.flush().unwrap();
        thread::sleep(Duration::from_millis(40));
    }
    // 2) 向服务进程发 SIGINT，触发取消/排空路径
    let st = Command::new("kill")
        .args(["-INT", &srv.pid().to_string()])
        .status()
        .expect("发送 SIGINT 失败");
    assert!(st.success(), "kill -INT 执行失败");
    thread::sleep(Duration::from_millis(150));
    // 3) 排空窗口内：在途连接必须仍能拿到完整响应
    s.write_all(b"\n").unwrap();
    let mut buf = [0u8; 512];
    let n = match s.read(&mut buf) {
        Ok(n) => n,
        Err(e) => panic!(
            "排空期内请求失败（在途连接被取消路径丢弃，部分读取未受保护）: {}",
            e
        ),
    };
    assert!(n > 0, "读到 EOF：SIGINT 后在途连接被立即关闭（无排空语义）");
    let resp = String::from_utf8_lossy(&buf[..n]);
    assert_eq!(resp.trim(), "MISS", "分片请求响应被破坏: {:?}", resp);
}

mod common;
use common::*;
use std::io::{Read, Write};
use std::net::TcpStream;
use std::time::{Duration, Instant};

// 任务3：通道治理 —— 禁用无界通道 + 流水线吞吐健康。
// buggy 版 state.rs 使用 unbounded_channel 且 rx 被丢弃 → 源码断言立即判负。
#[test]
fn bounded_channel_overload() {
    let src = std::fs::read_to_string("src/state.rs").expect("读取 src/state.rs");
    assert!(
        !src.contains("unbounded_channel"),
        "state.rs 仍在使用无界通道（任务3 要求改为有界 1024 并真实消费 rx）"
    );

    let _srv = start_server();
    let mut s = TcpStream::connect(ADDR).expect("connect");
    s.set_read_timeout(Some(Duration::from_secs(30))).unwrap();
    s.set_write_timeout(Some(Duration::from_secs(30))).unwrap();
    // 单连接流水线灌入 5000 个请求，不逐个等响应
    let mut payload = Vec::with_capacity(1 << 18);
    for i in 0..5000usize {
        payload.extend_from_slice(format!("bulk-{}\n", i).as_bytes());
    }
    s.write_all(&payload).expect("pipeline write");
    let want = 4 * 5000; // 每请求至少 4 字节（"MISS"）
    let mut buf = vec![0u8; 1 << 16];
    let mut total = 0usize;
    let dl = Instant::now() + Duration::from_secs(25);
    while total < want && Instant::now() < dl {
        match s.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => total += n,
            Err(_) => break,
        }
    }
    assert!(
        total >= want,
        "流水线响应字节不足 {}/{}（通道堵塞或消费端丢失）",
        total,
        want
    );
}

mod common;
use common::*;
use std::thread;
use std::time::Duration;

// 任务3：spawn 的任务句柄统一收集 —— 连接churn后 fd 数不得持续增长。
// 定位：辅助护栏（buggy 版主要在编译阶段即失败）；对修复回归有真实约束力。
#[test]
fn no_fd_leak_after_churn() {
    let srv = start_server();
    let pid = srv.pid();
    for _ in 0..300 {
        let _ = req(b"churn-a\n");
    }
    thread::sleep(Duration::from_millis(800));
    let base = fd_count(pid);
    assert!(base != usize::MAX, "无法读取 /proc fd（需要 Linux 环境）");
    for _ in 0..300 {
        let _ = req(b"churn-b\n");
    }
    thread::sleep(Duration::from_millis(800));
    let after = fd_count(pid);
    assert!(
        after <= base + 20,
        "fd 持续增长: {} -> {}（任务句柄/连接泄漏）",
        base,
        after
    );
}

