mod shard; pub mod iter; pub mod snapshot;

use shard::Shard;
use std::sync::RwLock;

pub struct ShardedMap {
    pub shards: Vec<RwLock<Shard>>,   // 公开字段便于白盒测试
}

impl ShardedMap {
    pub fn new(n: usize) -> Self {
        ShardedMap { shards: (0..n).map(|_| RwLock::new(Shard::new())).collect() }
    }
    // BUG —— 分片函数用简单求和哈希，相似键严重倾斜
    pub fn shard_of(&self, key: &str) -> usize {
        key.bytes().fold(0usize, |a, b| a.wrapping_add(b as usize)) % self.shards.len()
    }
    pub fn insert(&self, k: String, v: String) {
        let mut g = self.shards[self.shard_of(&k)].write().unwrap();
        g.insert(k, v);
    }
    pub fn get(&self, k: &str) -> Option<String> {
        self.shards[self.shard_of(k)].read().unwrap().get(k)
    }
    // BUG —— get_or_insert 先读后写，两步之间存在窗口导致重复插入
    pub fn get_or_insert(&self, k: String, v: String) -> String {
        if let Some(x) = self.get(&k) { return x; }
        self.insert(k.clone(), v.clone());
        v
    }
}

use std::collections::HashMap;

#[derive(Default)]
pub struct Shard { map: HashMap<String, String> }

impl Shard {
    pub fn new() -> Self { Shard { map: HashMap::new() } }
    pub fn insert(&mut self, k: String, v: String) { self.map.insert(k, v); }
    pub fn get(&self, k: &str) -> Option<String> { self.map.get(k).cloned() }
}

use crate::ShardedMap;

impl ShardedMap {
    /// BUG —— 一次性锁住全部分片再收集，与单分片写操作形成 ABBA 死锁
    pub fn iter_snapshot(&self) -> Vec<(String, String)> {
        let guards: Vec<_> = self.shards.iter().map(|s| s.read().unwrap()).collect();
        guards.iter()
            .flat_map(|g| g.entries())
            .collect()
    }
}

