use sharded_kv::ShardedMap;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

fn join_timeout(h: thread::JoinHandle<()>, d: Duration, what: &str) {
    let (tx, rx) = std::sync::mpsc::channel();
    thread::spawn(move || {
        let _ = h.join();
        let _ = tx.send(());
    });
    assert!(rx.recv_timeout(d).is_ok(), "{}：线程超时（疑似死锁）", what);
}

// 定位：辅助护栏 —— 防止重写 iter_snapshot 时引入真正的死锁。
// 硬判别由 get_or_insert_unique / shard_balance / remove_if_atomic 承担。
#[test]
fn cross_iter_write_no_deadlock() {
    let map = Arc::new(ShardedMap::new(8));
    for i in 0..30_000usize {
        map.insert(format!("seed-{}", i), format!("v{}", i));
    }
    let stop = Arc::new(AtomicBool::new(false));
    let mut writers = Vec::new();
    let mut iters = Vec::new();

    for _ in 0..2usize {
        let m = map.clone();
        let st = stop.clone();
        iters.push(thread::spawn(move || {
            while !st.load(Ordering::Relaxed) {
                let snap = m.iter_snapshot();
                for (k, v) in snap.iter().take(100) {
                    assert!(!k.is_empty() && !v.is_empty(), "快照出现空键值");
                }
            }
        }));
    }

    for w in 0..4usize {
        let m = map.clone();
        writers.push(thread::spawn(move || {
            for i in 0..25_000usize {
                m.insert(format!("w{}-{}", w, i), format!("v{}", i));
            }
        }));
    }

    let dl = Instant::now() + Duration::from_secs(60);
    for (i, h) in writers.into_iter().enumerate() {
        let left = dl.saturating_duration_since(Instant::now());
        assert!(!left.is_zero(), "写线程整体超时（{}/4）", i);
        join_timeout(h, left, &format!("writer-{}", i));
    }
    stop.store(true, Ordering::Relaxed);
    let dl2 = Instant::now() + Duration::from_secs(15);
    for (i, h) in iters.into_iter().enumerate() {
        let left = dl2.saturating_duration_since(Instant::now());
        assert!(!left.is_zero(), "迭代线程收尾超时（{}）", i);
        join_timeout(h, left, &format!("iterator-{}", i));
    }
}

use sharded_kv::ShardedMap;
use std::collections::HashSet;
use std::sync::{Arc, Mutex};
use std::thread;

// 任务2：get_or_insert 检查-插入竞态。64 线程并发同一键：
// 修复版所有线程观察到同一个值；buggy 版多个线程同时通过 miss 检查、
// 各自插入成功并返回自己的 winner → 集合大小 > 1 判负（宽窗口下近必然触发）。
#[test]
fn get_or_insert_observes_single_value() {
    let map = Arc::new(ShardedMap::new(8));
    let seen = Arc::new(Mutex::new(HashSet::new()));
    let mut hs = Vec::new();
    for t in 0..64usize {
        let m = map.clone();
        let s = seen.clone();
        hs.push(thread::spawn(move || {
            let v = m.get_or_insert("hot".into(), format!("winner-{}", t));
            s.lock().unwrap().insert(v);
        }));
    }
    for h in hs {
        h.join().unwrap();
    }
    let set = seen.lock().unwrap();
    assert_eq!(
        set.len(),
        1,
        "并发 get_or_insert 观察到 {} 个不同值（check-then-act 竞态未修复）：{:?}",
        set.len(),
        set
    );
    assert_eq!(map.get("hot"), set.iter().next().cloned());
}

use sharded_kv::ShardedMap;

// 任务3：分片哈希抗倾斜（确定性判别）。构造 10 万个"字节和 ≡ 0 (mod 8)"的对抗键 ——
// buggy 的求和哈希会把它们全部塞进同一个分片；
// 修复版（乘法混合/FxHash 类）应均匀散布，最大/最小分片负载比 < 2。
#[test]
fn skewed_keys_balanced() {
    let map = ShardedMap::new(8);
    for i in 0..100_000usize {
        let core = format!("item:{:06}", i);
        let sum: usize = core.bytes().map(|b| b as usize).sum();
        let pad = (8 - (sum % 8)) % 8; // 'Q' = 81 ≡ 1 (mod 8)
        let key = format!("{}{}", core, "Q".repeat(pad));
        map.insert(key, "x".into());
    }
    let snap = map.iter_snapshot();
    assert_eq!(snap.len(), 100_000, "快照条目数不符：{}", snap.len());
    let mut counts = vec![0usize; 8];
    for (k, _) in &snap {
        let idx = map.shard_of(k);
        assert!(idx < 8, "shard_of 越界：{}", idx);
        counts[idx] += 1;
    }
    let mn = *counts.iter().min().unwrap();
    let mx = *counts.iter().max().unwrap();
    assert!(mn > 0, "存在空分片，分布完全倾斜：{:?}", counts);
    let ratio = mx as f64 / mn as f64;
    assert!(
        ratio < 2.0,
        "对抗键下分片失衡（ratio={:.2}）：{:?}",
        ratio,
        counts
    );
}

use sharded_kv::ShardedMap;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

fn join_timeout(h: thread::JoinHandle<()>, d: Duration, what: &str) {
    let (tx, rx) = std::sync::mpsc::channel();
    thread::spawn(move || {
        let _ = h.join();
        let _ = tx.send(());
    });
    assert!(rx.recv_timeout(d).is_ok(), "{}：线程超时", what);
}

// 任务4：remove_if 原子条件删除。buggy 版缺少该方法 →
// 本测试目标编译失败 → cargo test 以非 0 退出（编译门判负）。
#[test]
fn remove_if_semantics_and_atomicity() {
    let map = ShardedMap::new(4);
    map.insert("a".into(), "del-me".into());
    map.insert("b".into(), "keep".into());
    assert!(
        map.remove_if("a", |v| v.starts_with("del")),
        "匹配项应删除并返回 true"
    );
    assert_eq!(map.get("a"), None, "删除后不应可读");
    assert!(!map.remove_if("b", |v| v.starts_with("del")), "不匹配应返回 false");
    assert_eq!(map.get("b"), Some("keep".into()));
    assert!(!map.remove_if("missing", |_v| true), "不存在的键应返回 false");

    // 并发交叉：偶数线程写 x{n}，奇数线程条件删除；终态必须自洽。
    let m = Arc::new(ShardedMap::new(4));
    let hits = Arc::new(AtomicUsize::new(0));
    let mut hs = Vec::new();
    for t in 0..8usize {
        let mm = m.clone();
        let hh = hits.clone();
        hs.push(thread::spawn(move || {
            for i in 0..5000usize {
                let k = format!("ck{}", i % 50);
                if t % 2 == 0 {
                    mm.insert(k, format!("x{}", i));
                } else if mm.remove_if(&k, |v| v.starts_with('x')) {
                    hh.fetch_add(1, Ordering::Relaxed);
                }
            }
        }));
    }
    let dl = Instant::now() + Duration::from_secs(30);
    for (i, h) in hs.into_iter().enumerate() {
        let left = dl.saturating_duration_since(Instant::now());
        assert!(!left.is_zero(), "并发阶段整体超时（{}）", i);
        join_timeout(h, left, &format!("t{}", i));
    }
    for i in 0..50usize {
        if let Some(v) = m.get(&format!("ck{}", i)) {
            assert!(v.starts_with('x'), "终态出现非法值：{}", v);
        }
    }
    assert!(
        hits.load(Ordering::Relaxed) > 0,
        "remove_if 从未成功删除（语义失效）"
    );
}

