export type Route =
  | { method: "GET"; path: "/api/users"; query?: { limit?: number } }
  | { method: "GET"; path: "/api/users/:id" }
  | { method: "POST"; path: "/api/users"; body: { name: string; email: string } };

export interface User { id: number; name: string; email: string }
export interface ApiError { status: number; message: string }

import { User } from "../shared/contract";

const users: User[] = [
  { id: 1, name: "Ada", email: "ada@example.com" },
  { id: 2, name: "Lin", email: "lin@example.com" },
];

export function listUsers(limit?: number): User[] {
  return typeof limit === "number" ? users.slice(0, limit) : users;
}
export function getUser(id: number): User | undefined {
  return users.find((u) => u.id === id);
}
export function addUser(u: User): User { users.push(u); return u; }
export function nextId(): number { return users.length + 1; }

import http from "http";
import { listUsers, getUser, addUser, nextId } from "./store";

// BUG —— POST body 完全信任客户端类型，无运行时校验
export function createApp() {
  return http.createServer((req, res) => {
    const url = new URL(req.url ?? "/", "http://localhost");
    if (req.method === "GET" && url.pathname === "/api/users") {
      const limit = Number(url.searchParams.get("limit")) || undefined;
      res.setHeader("Content-Type", "application/json");
      res.end(JSON.stringify(listUsers(limit)));
      return;
    }
    if (req.method === "GET" && url.pathname.startsWith("/api/users/")) {
      const id = Number(url.pathname.split("/")[3]);
      const u = getUser(id);
      if (!u) {
        res.statusCode = 404;
        res.end(JSON.stringify({ message: "not found" }));  // 信封不一致
      } else { res.end(JSON.stringify(u)); }
      return;
    }
    if (req.method === "POST" && url.pathname === "/api/users") {
      let raw = "";
      req.on("data", (c) => (raw += c));
      req.on("end", () => {
        const body = JSON.parse(raw);        // 盲信类型
        res.end(JSON.stringify(addUser({ id: nextId(), ...body })));
      });
      return;
    }
    res.statusCode = 404;
    res.end("{}");
  });
}

// BUG —— 与服务端重复手写 User，且响应盲目 cast
interface User { id: number; name: string; email: string }

async function request(path: string): Promise<User[]> {
  const r = await fetch(`http://localhost:3000${path}`);
  return (await r.json()) as User[];
}

export const api = {
  listUsers: () => request("/api/users"),
  getUser: async (id: number) =>
    ((await fetch(`http://localhost:3000/api/users/${id}`)).json()) as User,
};

