test("GET /api/users 返回列表", async () => {
  const s: Server = createApp();
  await new Promise<void>((res) => s.listen(3000, () => res()));
  try {
    const j = await (await fetch("http://localhost:3000/api/users?limit=1")).json();
    assert.ok(Array.isArray(j));
    assert.equal((j as unknown[]).length, 1);
  } finally {
    await new Promise<void>((res) => s.close(() => res()));
  }
});

