import fs from "fs";
import { createCsvParser } from "./csvParser";
import { createValidator } from "./validate";
import { createBatchWriter } from "./batchWriter";

// BUG —— 手工 pipe，无错误转发；任一环节出错进程静默挂起或崩溃
export function run(input: string, out: string) {
  const source = fs.createReadStream(input, { highWaterMark: 64 * 1024 });
  source.pipe(createCsvParser()).pipe(createValidator(out)).pipe(createBatchWriter(out));
  return { source };
}

if (require.main === module) {
  run(process.argv[2], process.argv[3]);
}

import { Transform } from "stream";

export function createCsvParser(): Transform {
  let buf = "";
  return new Transform({
    transform(chunk, _enc, cb) {
      // BUG —— chunk 可能从多字节字符中间截断；引号内换行未处理
      buf += chunk.toString();
      const lines = buf.split("\n");
      buf = lines.pop() ?? "";
      for (const line of lines) this.push(line + "\n");
      cb();
    },
    flush(cb) {
      if (buf) this.push(buf + "\n");
      cb();
    },
  });
}

import { Transform } from "stream";

export function createValidator(rejectsPath: string): Transform {
  return new Transform({
    objectMode: false,
    transform(lineBuf, _enc, cb) {
      const line = lineBuf.toString().trimEnd();
      const cols = line.split(",");
      // 合法行约定 —— 3 列且第 3 列为正整数
      if (cols.length !== 3 || !/^\d+$/.test(cols[2])) {
        require("fs").appendFileSync(rejectsPath + ".rejects", line + "\n");
        cb(); return;                 // 丢弃非法行
      }
      cb(null, lineBuf);
    },
  });
}

import { Writable } from "stream";
import fs from "fs";

export function createBatchWriter(out: string): Writable {
  let batch: string[] = [];
  return new Writable({
    write(chunk, _enc, cb) {
      batch.push(chunk.toString());
      // BUG —— 无定时/阈值刷写之外的背压考量，且从不落盘直到结束
      if (batch.length >= 500) {
        fs.appendFileSync(out, batch.join(""));
        batch = [];
      }
      cb();
    },
    flush(cb) {
      fs.appendFileSync(out, batch.join(""));
      cb();
    },
  });
}

import fs from "fs"; import os from "os"; import path from "path";
import { run } from "../src/index";

function mkfile(rows: string[]): string {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "pl-"));
  const p = path.join(dir, "in.csv");
  fs.writeFileSync(p, rows.join("\n"));
  return p;
}

it("合法行全部写出", () => {
  const inp = mkfile(["a,b,1", "c,d,2"]);
  const dir = path.dirname(inp);
  run(inp, path.join(dir, "out.txt"));
  expect(fs.readFileSync(path.join(dir, "out.txt"), "utf8").trim().split("\n")).toHaveLength(2);
