it("错误被统一上报而非静默", (done) => {   // 故意失败
  const inp = mkfile(["a,b,1"]);
  const dir = path.dirname(inp);
  const { source } = run(inp, path.join(dir, "out2.txt"));
  source.destroy(new Error("boom"));
  process.on("unhandledRejection", () => done.fail());
  setTimeout(done, 50);
