'use strict';
// 生成 ~60MB 合成 CSV，子进程跑管线：
// 校验 ① 行数守恒 ② 子进程 VmHWM < 150MB
const { spawn } = require('child_process');
const fs = require('fs'); const os = require('os'); const path = require('path');

async function main() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'bigcsv-'));
  const inp = path.join(dir, 'in.csv');
  const out = path.join(dir, 'out.txt');
  const TARGET_BYTES = 60 * 1024 * 1024;
  let rows = 0, bytes = 0;
  await new Promise((res) => {
    const ws = fs.createWriteStream(inp);
    function pump() {
      let ok = true;
      while (ok && bytes < TARGET_BYTES) {
        const line = `sku${rows},name-${rows}-paddingpadding-paddingpadding,${rows % 1000}\n`;
        bytes += line.length; rows++;
        ok = ws.write(line);
      }
      if (bytes >= TARGET_BYTES) ws.end(res); else ws.once('drain', pump);
    }
    pump();
  });

  const child = spawn(process.execPath,
    [path.join(__dirname, 'dist', 'tests', 'hidden', 'run_pipeline.js'), inp, out],
    { cwd: path.join(__dirname, '..', '..'), stdio: ['ignore', 'pipe', 'pipe'] });
  let peakKB = 0;
  const timer = setInterval(() => {
    try {
      const s = fs.readFileSync(`/proc/${child.pid}/status`, 'utf8');
      const m = /VmHWM:\s+(\d+)/.exec(s);
      if (m) peakKB = Math.max(peakKB, +m[1]);
    } catch { /* 进程已退出 */ }
  }, 25);
  let stderr = '';
  child.stderr.on('data', d => stderr += d);
  const code = await new Promise(r => child.on('close', c => { clearInterval(timer); r(c); }));
  if (code !== 0) { console.error('pipeline exit', code, stderr.slice(0, 500)); process.exit(1); }

  const cnt = f => { try { const t = fs.readFileSync(f, 'utf8').replace(/\n$/, ''); return t ? t.split('\n').length : 0; } catch { return 0; } };
  const outLines = cnt(out), rejLines = cnt(out + '.rejects');
  if (outLines + rejLines !== rows) {
    console.error(`行数守恒失败 out=${outLines} rej=${rejLines} 输入=${rows}`); process.exit(1);
  }
  const peakMB = Math.round(peakKB / 1024);
  console.log(`peak=${peakMB}MB rows=${rows}`);
  if (peakMB >= 150) { console.error(`内存峰值 ${peakMB}MB >= 150MB`); process.exit(1); }
  console.log('BIGFILE-OK');
}
main();

import { mkdtempSync, writeFileSync, readFileSync, existsSync } from 'fs';
import { tmpdir } from 'os';
import { join } from 'path';
import { run } from '../../src/index';

export function makeCsv(rows: string[]): string {
  const dir = mkdtempSync(join(tmpdir(), 'pl-'));
  const p = join(dir, 'in.csv');
  writeFileSync(p, rows.join('\n') + (rows.length ? '\n' : ''), 'utf8');
  return p;
}

export async function pipe(inp: string): Promise<{ out: string; rej: string }> {
  const dir = mkdtempSync(join(tmpdir(), 'pl-out-'));
  const out = join(dir, 'out.txt');
  const ret = run(inp, out) as unknown as { promise?: Promise<void> } | Promise<void>;
  const p = (ret && typeof (ret as { then?: unknown }).then === 'function')
    ? (ret as unknown as Promise<void>)
    : (ret as { promise?: Promise<void> })?.promise;
  if (p && typeof p.then === 'function') await p;
  return { out, rej: out + '.rejects' };
}

export const lines = (f: string): string[] => {
  if (!existsSync(f)) return [];
  const t = readFileSync(f, 'utf8').replace(/\n$/, '');
  return t ? t.split('\n') : [];
};

import { test } from 'node:test';
import assert from 'node:assert';
import { makeCsv, pipe, lines } from './helpers';

test('多字节字符跨 chunk 边界不被截断', async () => {
  // 构造填充行使特殊行起点落在 64KB 边界附近（highWaterMark=64KB）
  const pad = 'p'.repeat(65536 - 80);
  const rows = [
    `${pad},filler,1`,
    '标签🈶️中文,name😀字段,42',
    'plain,row,3',
  ];
  const { out, rej } = await pipe(makeCsv(rows));
  const good = lines(out);
  assert.ok(good.some(l => l.includes('标签')), `中文字段丢失: ${JSON.stringify(good)}`);
  assert.ok(good.some(l => l.includes('😀')), `emoji 丢失`);
  assert.ok(good.some(l => /,42$/.test(l)), '多字节行的第三列损坏');
  assert.equal(lines(rej).length, 0, `合法行被误拒: ${lines(rej)}`);
});

import { test } from 'node:test';
