test('RFC4180 引号字段（含逗号/换行）正确解析', async () => {
  const dir = mkdtempSync(join(tmpdir(), 'quoted-'));
  const inp = join(dir, 'q.csv');
  writeFileSync(inp, 'a,"x,y",7\nx,"line1\nline2",9\nend,row,1\n');
  const { out, rej } = await pipe(inp);
  const body = readFileSync(out, 'utf8');
  assert.ok(body.includes('"x,y"') || body.includes('x,y'), '引号内逗号处理错误');
  assert.ok(body.includes('line1\nline2'), '引号内换行被拆散');
  assert.equal(lines(rej).length, 0, `含引号的合法行进入 rejects: ${lines(rej)}`);
  assert.ok(body.includes('end,row,1'), '后续行错位丢失');
