test('阈值刷写：500 条即落盘（不必等结束）', async () => {
  const dir = mkdtempSync(join(tmpdir(), 'bw-'));
  const out = join(dir, 'o.txt');
  const w = createBatchWriter(out);
  for (let i = 0; i < 600; i++) {
    if (!w.write(Buffer.from(`row-${i}\n`))) {
      await new Promise<void>(r => w.once('drain', () => r()));
    }
  }
  const mid = existsSync(out) ? readFileSync(out, 'utf8').split('\n').filter(Boolean).length : 0;
  assert.ok(mid >= 500, `600 条写入后中途仅落盘 ${mid} 条（未实现 500 条阈值刷写）`);
  w.end();
  await new Promise<void>(r => w.on('finish', () => r()));
  const fin = readFileSync(out, 'utf8').split('\n').filter(Boolean).length;
  assert.equal(fin, 600, '结束后总数不符');
});

test('目标不可写时 run().promise 必须 reject（统一错误传播）', async () => {
  const dir = mkdtempSync(join(tmpdir(), 'ab-'));
  const inp = join(dir, 'in.csv');
  writeFileSync(inp, 'a,b,1\n');
  const roDir = join(dir, 'ro');
  mkdirSync(roDir);
  const badOut = roDir;
  const ret = run(inp, badOut) as { promise?: Promise<void> };
  let rejected = false;
  try {
    const p = ret.promise ?? Promise.resolve();
    await p;
  } catch { rejected = true; }
  assert.ok(rejected, '管线失败未通过 promise reject 上抛（静默吞错）');
});

