{
  "name": "plugin-host",
  "private": true,
  "scripts": {
    "test": "jest"
  },
  "devDependencies": {
    "typescript": "^5.4.5",
    "@types/node": "^20.12.7"
  }
}

import { EventEmitter } from "events";

// BUG —— 事件名与载荷无类型关联
export class PluginBus extends EventEmitter {}

export const bus = new PluginBus();

import { bus } from "./emitter";

export interface PluginManifest {
  name: string;
  requires: string[];
  setup(): void;
  teardown?(): void;
}

const registered = new Map<string, PluginManifest>();
const loaded: string[] = [];

export function register(p: PluginManifest): void {
  registered.set(p.name, p);
}

// BUG —— 按注册顺序加载，不校验依赖；循环依赖时 while 死循环
export function loadAll(): string[] {
  for (const p of registered.values()) {
    p.setup();
    loaded.push(p.name);
  }
  return [...loaded];
}

export function reset(): void {
  loaded.length = 0;
  registered.clear();
  bus.removeAllListeners();
}

import { bus } from "../emitter";
import { register } from "../registry";

export function loggerPlugin() {
  return {
    name: "logger",
    requires: [],
    setup() { bus.on("request", (p: any) => console.log("[log]", p)); },
    teardown() { bus.off("request", () => undefined); },  // BUG —— 匿名函数无法解绑
  };
}

import { register } from "../registry";

export function authPlugin() {
  return {
    name: "auth",
    requires: ["logger"],
    setup() {},
  };
}

import { register } from "../registry";

export function cachePlugin() {
  return {
    name: "cache",
    requires: ["auth"],   // 与 auth 构成环（auth 亦声明依赖 cache 的场景由测试注入）
    setup() {},
  };
}

import { register, loadAll, reset } from "../src/registry";
import { loggerPlugin } from "../src/plugins/logger";
import { authPlugin } from "../src/plugins/auth";

beforeEach(reset);

it("乱序注册也能按依赖加载", () => {
  register(authPlugin()); register(loggerPlugin());
  expect(loadAll()).toEqual(["logger", "auth"]);
});

it("循环依赖抛出明确异常", () => {          // 故意失败
  register({ name: "a", requires: ["b"], setup() {}, teardown() {} });
  register({ name: "b", requires: ["a"], setup() {}, teardown() {} });
  expect(() => loadAll()).toThrow(/circular/i);
});

